/* Generated by WebPort v1. Edits will be overwritten. */
#include "hbx_sdk.h"
#include "hbx_app.h"
#include "hbx_ui.h"

static void append_uint(char *out, unsigned value) {
    char reverse[12]; unsigned n=0, i=0;
    do { reverse[n++]=(char)('0'+(value%10u)); value/=10u; } while(value && n<sizeof reverse);
    while(n) out[i++]=reverse[--n];
    out[i]=0;
}

int hbx_app_main(const struct hbx_ctx *ctx) {
    struct hbx_input_state input; uint64_t deadline=0; uint32_t frames=0;
    uint32_t selected=0, count=0; char count_text[12];
    uint32_t last_touch_id=0xffffffffu, t;
    char button_labels[1][96] = {"Clicked 0 times"};
    if(hbx_ctx_check(ctx)!=HBX_OK) return HBX_ERR_ABI;
    hbx_memset(&input,0,sizeof input);
    hbx_log(ctx, "WebPort native UI started");
    while(!hbx_stop_requested(ctx)) {
        hbx_input_poll(ctx,&input);
        if(input.pressed & (HBX_B|HBX_PLUS)) break;
        if(input.pressed & HBX_DOWN) selected=(selected+1u)%1u;
        if(input.pressed & HBX_UP) selected=(selected+0u)%1u;
        if((input.pressed & HBX_A) && selected==0u) { count++; append_uint(count_text,count);
            hbx_memcpy(button_labels[0], "Clicked ", 8);
            hbx_memcpy(button_labels[0]+8, count_text, hbx_strlen(count_text));
            hbx_memcpy(button_labels[0]+8+hbx_strlen(count_text), count==1u ? " time" : " times", count==1u ? 5u : 6u);
            button_labels[0][8+hbx_strlen(count_text)+(count==1u?5u:6u)]=0; }
        if(input.touch_count==0u) last_touch_id=0xffffffffu;
        for(t=0;t<input.touch_count && t<HBX_MAX_TOUCH;t++) {
            if(hbx_touch_hit(&input.touch[t],232,526,1456,68)) {
                selected=0u;
                if(last_touch_id!=input.touch[t].id) { count++; append_uint(count_text,count);
            hbx_memcpy(button_labels[0], "Clicked ", 8);
            hbx_memcpy(button_labels[0]+8, count_text, hbx_strlen(count_text));
            hbx_memcpy(button_labels[0]+8+hbx_strlen(count_text), count==1u ? " time" : " times", count==1u ? 5u : 6u);
            button_labels[0][8+hbx_strlen(count_text)+(count==1u?5u:6u)]=0; }
                last_touch_id=input.touch[t].id;
            }
        }
        hbx_ui_begin(ctx, HBX_RGB(16, 21, 16));
        hbx_ui_rect(ctx, 152.0f, 112.0f, 1616.0f, 856.0f, 24.0f, HBX_RGB(23, 30, 24));
        hbx_ui_stroke(ctx, 152.0f, 112.0f, 1616.0f, 856.0f, 24.0f, 2.0f, HBX_RGB(51, 67, 50));
        hbx_ui_text(ctx, 232.0f, 220.0f, HBX_FONT_H1, "Hello from TypeScript", HBX_RGB(237, 244, 233));
        hbx_ui_text(ctx, 232.0f, 370.0f, HBX_FONT_BODY, "BRENDAN WEB APP · VITE + TYPESCRIPT", HBX_RGB(237, 244, 233));
        hbx_ui_text(ctx, 232.0f, 422.0f, HBX_FONT_BODY, "This TypeScript source is bundled into static HTML, CSS, and JavaScript.", HBX_RGB(237, 244, 233));
        hbx_ui_text(ctx, 232.0f, 474.0f, HBX_FONT_BODY, "This browser app is served by BrendanLauncher on the host PC.", HBX_RGB(237, 244, 233));
        hbx_ui_rect(ctx, 232.0f, 526.0f, 1456.0f, 68.0f, 12.0f, selected == 0u ? HBX_RGB(51, 78, 39) : HBX_RGB(162, 239, 93));
        hbx_ui_stroke(ctx, 232.0f, 526.0f, 1456.0f, 68.0f, 12.0f, 2.0f, selected == 0u ? HBX_RGB(162, 239, 93) : HBX_RGB(67, 85, 65));
        hbx_ui_text(ctx, 260.0f, 546.0f, HBX_FONT_BODY, button_labels[0], HBX_RGB(20, 32, 13));
        hbx_ui_text(ctx, 232.0f, 900.0f, HBX_FONT_SMALL, "Touch/A: activate  ·  B: return  ·  D-pad: select", HBX_RGB(165, 184, 158));
        hbx_ui_present(ctx); frames++; hbx_frame_end(ctx); hbx_pace(ctx,&deadline,60);
    }
    hbx_logf(ctx,"WebPort exited after %u frames",frames);
    return HBX_OK;
}
